// agdBigGraph builds a connected undirected graph with n nodes and m edges
// (a random tree first, then random extras) with weights up to a million.
func agdBigGraph(n, m int) [][]int {
	state := uint64(12345)
	next := func() int {
		state = state*6364136223846793005 + 1442695040888963407
		return int(state >> 33)
	}
	edges := make([][]int, 0, m)
	for v := 1; v < n; v++ {
		edges = append(edges, []int{next() % v, v, 1 + next()%1000000})
	}
	for len(edges) < m {
		u, v := next()%n, next()%n
		if u != v {
			edges = append(edges, []int{u, v, 1 + next()%1000000})
		}
	}
	return edges
}

// agdMSTWeight is Kruskal's algorithm, used to compute the expected answer.
func agdMSTWeight(n int, edges [][]int) int {
	sorted := append([][]int(nil), edges...)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i][2] < sorted[j][2] })
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	var find func(int) int
	find = func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	total := 0
	for _, e := range sorted {
		if ru, rv := find(e[0]), find(e[1]); ru != rv {
			parent[ru] = rv
			total += e[2]
		}
	}
	return total
}
